uid_t effective_uid;

// Get the Effective User ID (EUID)
effective_uid = geteuid();

/*
The EUID determines file access permissions.
It can differ from the Real User ID (RUID)
in SUID programs.
*/

// Example check for root privileges:
if (geteuid() == 0) {
    // Process has effective root access
}
